<script lang="ts">
  import { onMount } from 'svelte';
  import SegmentedControl from './SegmentedControl.svelte';
  import type { ControlSize } from './SegmentedControl.svelte';

  let {
    value = $bindable<'light' | 'dark' | 'system'>('system'),
    size = 'md',
    onChange,
    onResolvedChange
  }: {
    value?: 'light' | 'dark' | 'system';
    size?: ControlSize;
    /** When provided, the host app owns the theme: no direct DOM writes here. */
    onChange?: (value: 'light' | 'dark' | 'system') => void;
    onResolvedChange?: (theme: 'light' | 'dark') => void;
  } = $props();
  let systemDark = $state(false);

  onMount(() => {
    const query = window.matchMedia('(prefers-color-scheme: dark)');
    const update = () => { systemDark = query.matches; };
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  });

  $effect(() => {
    const resolved = value === 'system' ? (systemDark ? 'dark' : 'light') : value;
    if (!onChange) document.documentElement.dataset.theme = resolved;
    onResolvedChange?.(resolved);
  });
</script>

